 [Serializable] public class Report {public string unity_version,graph_path,graph_guid,graph_file_id;public MaterialData[] materials;public bool source_materials_unchanged,shader_passes_gpu_compiled=false,full_import=false;}
 public static void Export(){var args=Environment.GetCommandLineArgs();int index=Array.IndexOf(args,"--openrpg-manifest");if(index<0)throw new Exception("Manifest absent");var r=JsonUtility.FromJson<Request>(File.ReadAllText(args[index+1]));if(File.Exists(r.output)||File.Exists(r.generated_shader))throw new Exception("Preserve prior receipts");if(r.material_guids.Length!=3||r.material_guids.Distinct().Count()!=3)throw new Exception("Exactly three original private materials required");var rows=new List<MaterialData>();var sources=new List<Material>();var originals=new List<string>();foreach(string guid in r.material_guids){var path=AssetDatabase.GUIDToAssetPath(guid);if(!path.StartsWith("Assets/OpenRPGTorchOriginalVariantV134/",StringComparison.Ordinal))throw new Exception("Material outside isolated source fragment");var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null)throw new Exception("Material missing");string g;long id;if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m,out g,out id)||g!=guid||id!=2100000)throw new Exception("Wrong material identity");var before=EditorJsonUtility.ToJson(m,true);sources.Add(m);originals.Add(before);var shader=m.shader;if(shader==null||!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(shader,out g,out id)||g!=r.graph_guid||id.ToString()!=r.graph_file_id)throw new Exception("Wrong source shader identity");if(AssetDatabase.GetAssetPath(shader)!=r.graph_path)throw new Exception("Shader graph path differs");var props=new List<Property>();for(int i=0;i<shader.GetPropertyCount();i++){string name=shader.GetPropertyName(i);var type=shader.GetPropertyType(i);var p=new Property{name=name,type=type.ToString()};switch(type){case ShaderPropertyType.Float:case ShaderPropertyType.Range:p.value_float=m.GetFloat(name);p.default_float=shader.GetPropertyDefaultFloatValue(i);break;case ShaderPropertyType.Int:p.value_float=m.GetInteger(name);p.default_float=shader.GetPropertyDefaultIntValue(i);break;case ShaderPropertyType.Color:var c=m.GetColor(name);p.value_vector=new Vector4(c.r,c.g,c.b,c.a);p.default_vector=shader.GetPropertyDefaultVectorValue(i);break;case ShaderPropertyType.Vector:p.value_vector=m.GetVector(name);p.default_vector=shader.GetPropertyDefaultVectorValue(i);break;case ShaderPropertyType.Texture:var t=m.GetTexture(name);p.texture_null=t==null;p.default_texture_name=shader.GetPropertyTextureDefaultName(i);p.texture_scale=m.GetTextureScale(name);p.texture_offset=m.GetTextureOffset(name);if(t!=null){if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(t,out g,out id))throw new Exception("Unidentified native texture");p.texture_guid=g;p.texture_file_id=id.ToString();}break;default:throw new Exception("Unknown native property kind");}props.Add(p);}var passes=new List<Pass>();for(int i=0;i<m.passCount;i++){var name=m.GetPassName(i);if(string.IsNullOrEmpty(name)||name.StartsWith("<Unnamed"))throw new Exception("Unnamed source pass");passes.Add(new Pass{name=name,enabled=m.GetShaderPassEnabled(name)});}if(before!=EditorJsonUtility.ToJson(m,true))throw new Exception("Material mutated");rows.Add(new MaterialData{guid=guid,file_id="2100000",name=m.name,serialized_json=before,render_queue=m.renderQueue,keywords=m.shaderKeywords,properties=props.ToArray(),passes=passes.ToArray(),source_material_unchanged=true});}
 var importer=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("UnityEditor.ShaderGraph.ShaderGraphImporter")).First(t=>t!=null);var method=importer.GetMethods(BindingFlags.Static|BindingFlags.NonPublic).Single(m=>m.Name=="GetShaderText"&&m.GetParameters().Length==4&&m.GetParameters()[0].ParameterType==typeof(string)&&m.GetParameters()[3].IsOut);object[] shaderArgs={r.graph_path,null,null,null};string text=(string)method.Invoke(null,shaderArgs);if(string.IsNullOrEmpty(text)||text.Contains("Hidden/GraphErrorShader2"))throw new Exception("Actual generated shader unavailable");for(int i=0;i<sources.Count;i++)if(originals[i]!=EditorJsonUtility.ToJson(sources[i],true))throw new Exception("Source mutated during generation");File.WriteAllText(r.generated_shader,text,new System.Text.UTF8Encoding(false));File.WriteAllText(r.output,JsonUtility.ToJson(new Report{unity_version=Application.unityVersion,graph_path=r.graph_path,graph_guid=r.graph_guid,graph_file_id=r.graph_file_id,materials=rows.ToArray(),source_materials_unchanged=true},true));
 OpenRPGTorchCompressedStorageV159.Export();
 }
}
